package br.com.athletix.notificacao.controller; import br.com.athletix.notificacao.service.*; import br.com.athletix.security.*; import jakarta.servlet.http.*; import org.springframework.security.core.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/notificacoes") public class NotificacaoController{final NotificacaoService s;final AutorizacaoAtualService a;public NotificacaoController(NotificacaoService s,AutorizacaoAtualService a){this.s=s;this.a=a;}@GetMapping public Object l(Authentication x,HttpServletRequest r){return s.listar(a.membroAtual(x,r).getId());}@GetMapping("/resumo") public java.util.Map<String,Long> z(Authentication x,HttpServletRequest r){return java.util.Map.of("naoLidas",s.naoLidas(a.membroAtual(x,r).getId()));}@PatchMapping("/{id}/ler") public Object read(@PathVariable Long id,Authentication x,HttpServletRequest r){return s.ler(id,a.membroAtual(x,r).getId());}}
